#!/usr/bin/env python3
# JACB - JACB Ain't Chromium Brother
import base64
import json
import os
import sys
import tempfile
from urllib.parse import quote

import gi
gi.require_version("Gdk", "4.0")
gi.require_version("Gtk", "4.0")
gi.require_version("WebKit", "6.0")
from gi.repository import Gdk, Gio, GLib, Gtk, Pango, WebKit

HOME = "jacb://start"
ICON_B64 = ""

START_HTML = """<!doctype html>
<meta charset="utf-8">
<title>JACB</title>
<style>
  body { margin:0; height:100vh; display:flex; flex-direction:column;
         align-items:center; justify-content:center; gap:1.2rem;
         background:#111; color:#eee; font-family:system-ui,sans-serif; }
  img { margin-bottom:-.4rem; }
  h1 { margin:0; font-size:4rem; letter-spacing:.2rem; }
  input { width:min(520px,80vw); padding:.8rem 1.2rem; font-size:1.1rem;
          border:1px solid #333; border-radius:999px; background:#1b1b1b;
          color:#eee; outline:none; }
  input:focus { border-color:#7c5cff; }
  nav { display:flex; gap:1.2rem; }
  a { color:#9a8cff; text-decoration:none; }
</style>
<img src="data:image/png;base64,%%ICON%%" width="140" height="140" alt="">
<h1>JACB</h1>
<form action="https://duckduckgo.com/" method="get">
  <input name="q" placeholder="search or type a url" autofocus>
</form>
<nav>
  <a href="https://github.com">github</a>
  <a href="https://youtube.com">youtube</a>
  <a href="https://wikipedia.org">wikipedia</a>
</nav>
"""


BLOCK_DOMAINS = [
    "doubleclick.net", "googlesyndication.com", "googleadservices.com",
    "googletagservices.com", "adservice.google.com", "google-analytics.com",
    "connect.facebook.net", "scorecardresearch.com", "taboola.com",
    "outbrain.com", "adnxs.com", "criteo.com", "criteo.net",
    "amazon-adsystem.com", "hotjar.com", "quantserve.com", "moatads.com",
    "pubmatic.com", "rubiconproject.com", "openx.net", "adsrvr.org",
    "ads-twitter.com", "analytics.twitter.com", "mathtag.com", "casalemedia.com",
    "advertising.com", "adform.net", "smartadserver.com", "2mdn.net",
    "zedo.com", "bidswitch.net", "sharethrough.com", "yieldmo.com",
]
HIDE = ".adsbygoogle, ins.adsbygoogle, [id^='google_ads'], [id^='div-gpt-ad']"
# run suaijp.py to generate this
USER_FILTERS = os.path.expanduser("~/.config/jacb/filters.json")


def load_suaijp(ucm):
    """SUAIJP blocker: built-in rules + ~/.config/jacb/filters.json (made by suaijp.py).
    Compiled once, cached by file mtime. Falls back to built-ins if WebKit rejects the big list."""
    base = [{"trigger": {"url-filter": r"^[a-z]+://([^/:]+\.)?" + d.replace(".", r"\.") + r"[:/]"},
             "action": {"type": "block"}} for d in BLOCK_DOMAINS]
    base.append({"trigger": {"url-filter": ".*"},
                 "action": {"type": "css-display-none", "selector": HIDE}})
    store = WebKit.UserContentFilterStore.new(
        os.path.expanduser("~/.cache/jacb/filters"))

    def add(st, res, finish, quiet=False):
        try:
            ucm.add_filter(finish(res))
            return True
        except GLib.Error as e:
            if not quiet:
                print("SUAIJP: filter failed:", e.message)
            return False

    def compile_base():
        store.save("suaijp-base", GLib.Bytes.new(json.dumps(base).encode()), None,
                   lambda st, res: add(st, res, st.save_finish))

    try:
        mtime = int(os.path.getmtime(USER_FILTERS))
    except OSError:
        return compile_base()
    ident = "suaijp-%d" % mtime

    def compile_full():
        try:
            with open(USER_FILTERS) as f:
                rules = base + json.load(f)
        except (OSError, ValueError) as e:
            print("SUAIJP: bad filters.json:", e)
            return compile_base()
        data = GLib.Bytes.new(json.dumps(rules).encode())

        def saved(st, res):
            if not add(st, res, st.save_finish):
                compile_base()
        store.save(ident, data, None, saved)

    def loaded(st, res):
        if not add(st, res, st.load_finish, quiet=True):
            compile_full()
    store.load(ident, None, loaded)


def setup_icon():
    d = tempfile.mkdtemp(prefix="jacb-")
    p = os.path.join(d, "hicolor", "256x256", "apps")
    os.makedirs(p)
    with open(os.path.join(p, "jacb.png"), "wb") as f:
        f.write(base64.b64decode(ICON_B64))
    Gtk.IconTheme.get_for_display(Gdk.Display.get_default()).add_search_path(d)
    Gtk.Window.set_default_icon_name("jacb")


def serve(req):
    data = START_HTML.replace("%%ICON%%", ICON_B64).encode()
    stream = Gio.MemoryInputStream.new_from_bytes(GLib.Bytes.new(data))
    req.finish(stream, len(data), "text/html")


def activate(app):
    Gtk.Settings.get_default().set_property("gtk-application-prefer-dark-theme", True)
    setup_icon()
    WebKit.WebContext.get_default().register_uri_scheme("jacb", serve)
    win = Gtk.ApplicationWindow(application=app, title="JACB",
                                default_width=1100, default_height=750)
    ucm = WebKit.UserContentManager()
    nb = Gtk.Notebook(scrollable=True)
    url = Gtk.Entry(hexpand=True)

    def cur():
        i = nb.get_current_page()
        return nb.get_nth_page(i) if i >= 0 else None

    def close_tab(web):
        nb.remove_page(nb.page_num(web))
        if nb.get_n_pages() == 0:
            win.close()

    def attach_tab(web, switch=True):
        label = Gtk.Label(label="New Tab", ellipsize=Pango.EllipsizeMode.END,
                          width_chars=14, max_width_chars=18, xalign=0)
        close = Gtk.Button(icon_name="window-close-symbolic", has_frame=False)
        close.connect("clicked", lambda _: close_tab(web))
        tab = Gtk.Box(spacing=6)
        tab.append(label)
        tab.append(close)
        web.connect("notify::title",
                    lambda w, _: label.set_text(w.get_title() or "New Tab"))
        web.connect("notify::uri",
                    lambda w, _: url.set_text(w.get_uri() or "") if w is cur() else None)
        web.connect("notify::is-loading",
                    lambda w, _: sync_nav() if w is cur() else None)
        web.connect("load-changed",
                    lambda w, _: sync_nav() if w is cur() else None)
        web.connect("create", on_create)
        web.connect("close", close_tab)          # window.close()
        page = nb.append_page(web, tab)
        if switch:
            nb.set_current_page(page)
        return web

    def new_tab(uri=HOME):
        web = attach_tab(WebKit.WebView(user_content_manager=ucm))
        web.load_uri(uri)
        return web

    def on_create(web, _nav_action):
        """target="_blank", middle-click and window.open() all land here.

        related_view keeps the popup in the opener's web process (WebKit
        requires it for views returned from ::create), but it does NOT carry
        over the user content manager -- pass ucm or SUAIJP wouldn't apply.
        """
        new = WebKit.WebView(related_view=web, user_content_manager=ucm)
        attach_tab(new, switch=False)
        # WebKit loads the URI itself; only surface the tab once it's ready.
        new.connect("ready-to-show",
                    lambda w: nb.set_current_page(nb.page_num(w)))
        return new

    def go(entry):
        t = entry.get_text().strip()
        if t.startswith("jacb:"):
            pass
        elif "." in t and " " not in t:
            t = t if t.startswith(("http://", "https://")) else "https://" + t
        else:
            t = "https://duckduckgo.com/?q=" + quote(t)
        if cur():
            cur().load_uri(t)
            cur().grab_focus()

    url.connect("activate", go)
    def switched(_nb, page, _i):
        url.set_text(page.get_uri() or "")
        sync_nav(page)       # get_current_page() is still stale in this handler

    nb.connect("switch-page", switched)

    def reload_or_stop(*_):
        web = cur()
        if web is None:
            return
        web.stop_loading() if web.is_loading() else web.reload()

    def focus_url(*_):
        url.grab_focus()
        url.select_region(0, -1)

    def sync_nav(web=None):
        """Keep reload/stop and back/forward in step with the visible tab."""
        web = web or cur()
        loading = bool(web and web.is_loading())
        reload_btn.set_icon_name("process-stop-symbolic" if loading
                                 else "view-refresh-symbolic")
        reload_btn.set_tooltip_text("Stop" if loading else "Reload")
        back.set_sensitive(bool(web and web.can_go_back()))
        fwd.set_sensitive(bool(web and web.can_go_forward()))

    back = Gtk.Button(icon_name="go-previous-symbolic", tooltip_text="Back")
    fwd = Gtk.Button(icon_name="go-next-symbolic", tooltip_text="Forward")
    reload_btn = Gtk.Button(icon_name="view-refresh-symbolic",
                            tooltip_text="Reload")
    plus = Gtk.Button(icon_name="tab-new-symbolic", tooltip_text="New Tab")
    back.connect("clicked", lambda _: cur() and cur().go_back())
    fwd.connect("clicked", lambda _: cur() and cur().go_forward())
    reload_btn.connect("clicked", reload_or_stop)
    plus.connect("clicked", lambda _: new_tab())

    for name, accels, fn in (
            ("new-tab", ["<Ctrl>t"], lambda *_: new_tab()),
            ("close-tab", ["<Ctrl>w"], lambda *_: cur() and close_tab(cur())),
            ("focus-url", ["<Ctrl>l", "F6"], focus_url),
            ("reload", ["<Ctrl>r", "F5"], reload_or_stop)):
        act = Gio.SimpleAction.new(name, None)
        act.connect("activate", fn)
        win.add_action(act)
        app.set_accels_for_action("win." + name, accels)

    bar = Gtk.HeaderBar()
    bar.pack_start(back)
    bar.pack_start(fwd)
    bar.pack_start(reload_btn)
    bar.pack_start(plus)
    bar.set_title_widget(url)
    win.set_titlebar(bar)
    win.set_child(nb)

    new_tab()
    sync_nav()
    win.present()
    load_suaijp(ucm)


app = Gtk.Application(application_id="me.jacb.browser")
app.connect("activate", activate)
sys.exit(app.run(None))
